void Solver::bump_var(int var, double coeff) {
    if (coeff <= 0.0) return;
    const double MAX_ACT = 1e100;
    const double RESCALE = 1e-100;
    static bool pending_rescale = false;

    activity[var] += var_inc * coeff;
    if (activity[var] > MAX_ACT) pending_rescale = true;

    if (pending_rescale) {
        for (int i = 1; i <= vars; ++i) activity[i] *= RESCALE;
        var_inc *= RESCALE;
        pending_rescale = false;
    }

    if (vsids.inHeap(var)) vsids.update(var);
}
